const _MALICE_COST_MUL=0.5; // 악의 소비 50% 할인
function _malCost(v){
  const _n=Number(v)||0;
  if(_n<=0)return 0;
  return Math.max(1,Math.ceil(_n*_MALICE_COST_MUL));
}

executed.addPotion:
function addPotion(type,count){
  count=count||1;
  // HP 물약은 즉시 '악의' 자원으로 전환
  if(type==='hp'){
    G.mats+=count;
    SFX.pickup();
    addTxt(P.x,P.y-20,`+${count}`,'#cc66ff',25);
    return true;
  }
  if(!POT[type])return false; // 포션 퀵슬롯 폐지(2026-10-10): HP만 존재(즉시 악의 전환), 그 외 종류는 버린다
  // Try to stack onto existing slot of same type
  for(let i=0;i<4;i++){if(QSLOTS[i].type===type){QSLOTS[i].count+=count;SFX.pickup();_requestQSRefresh();return true}}
  // Try to put in empty slot
  for(let i=0;i<4;i++){if(!QSLOTS[i].type){QSLOTS[i].type=type;QSLOTS[i].count=count;SFX.pickup();_requestQSRefresh();return true}}
  // Full
  notify(_T('퀵슬롯이 가득 찼습니다!'));return false;
}

