function _fgCraft(e){
  if(!_forgeSel)return;
  const s=_forgeSel;
  var _cnt=(e&&(e.shiftKey||e.ctrlKey))?10:1;
  var _done=0;
  for(var _ci=0;_ci<_cnt;_ci++){
    if(G.mats<s.cost)break;
    s.fn();_done++;
  }
  if(_done===0){notify(_T('악의가 부족합니다!'));return}
  _forgeSel=null;renderForge();dbSaveNow();
}
